def ensure_images(target_dir="images"):
    """Создаёт папку images/ и распаковывает в неё все картинки карт, если их ещё нет."""
    import base64 as _b64, os as _os
    _os.makedirs(target_dir, exist_ok=True)
    for name, b64_parts in IMAGES.items():
        path = _os.path.join(target_dir, name)
        if _os.path.exists(path):
            continue
        with open(path, "wb") as fh:
            fh.write(_b64.b64decode(b64_parts))
